<?php get_header(); ?><main id="content" class="site-content rp-container"><header class="page-heading"><h1><?php printf(esc_html__('Search results for: %s','rss-prism'),'<span>'.esc_html(get_search_query()).'</span>'); ?></h1><?php get_search_form(); ?></header><div class="single-layout<?php echo get_theme_mod('rss_prism_show_sidebar',true)&&is_active_sidebar('sidebar-1')?'':' single-layout--no-sidebar'; ?>"><div><?php if(have_posts()):?><div class="entry-grid"><?php while(have_posts()):the_post();rss_prism_post_card();endwhile;?></div><?php the_posts_pagination(); ?><?php else:?><div class="entry-card entry-card--plain"><h2><?php esc_html_e('No results found','rss-prism'); ?></h2><?php get_search_form(); ?></div><?php endif;?></div><?php rss_prism_sidebar();?></div></main><?php get_footer(); ?>